                var discriminatorValue = reader.GetString();
                if (discriminatorValue is not null && definition.DiscriminatorCases.TryGetValue(discriminatorValue, out var caseType)) return caseType;
                return definition.RawFallbackCase ?? definition.TagFallbackCase ?? definition.UnknownDiscriminatorFallbackCase;
            }

            if (definition.NeedsStructuralFallback)
            {
                for (var index = 0; index < definition.Cases.Length; index++)
                {
                    if (!definition.Cases[index].ContainsUniqueProperty(reader)) continue;
                    if (matchedCase >= 0 && matchedCase != index) return null;
                    matchedCase = index;
                }
            }

            if (!reader.Read()) return null;
            reader.Skip();
        }

        if (definition.AllowUnknownDiscriminator) return null;
        if (definition.DiscriminatorProperty is not null && definition.DefaultCase is not null) return definition.DefaultCase;
        if (definition.DiscriminatorIsComplete) return null;
        if (matchedCase >= 0) return definition.Cases[matchedCase].CaseType;
        if (observedProperties is not null)
        {
            var requiredMatch = -1;
            for (var index = 0; index < definition.Cases.Length; index++)
            {
                if (!definition.Cases[index].HasAllRequiredProperties(observedProperties)) continue;
                if (requiredMatch >= 0) return null;
                requiredMatch = index;
            }
            if (requiredMatch >= 0) return definition.Cases[requiredMatch].CaseType;
        }
        return definition.RawFallbackCase ?? definition.DefaultCase;
    }

    private static Type? ClassifyArray(ref Utf8JsonReader reader, UnionClassifierDefinition definition)
    {
        if (!reader.Read()) return null;
        if (reader.TokenType == JsonTokenType.EndArray) return definition.DefaultCase ?? definition.CaseTypes[0];
        if (reader.TokenType != JsonTokenType.StartObject) return null;

        var matchedCase = -1;
        var observedProperties = new HashSet<string>(StringComparer.Ordinal);
        while (reader.Read() && reader.TokenType != JsonTokenType.EndObject)
        {
            if (reader.TokenType != JsonTokenType.PropertyName) continue;
            if (reader.GetString() is { } propertyName) observedProperties.Add(propertyName);
            for (var index = 0; index < definition.Cases.Length; index++)
            {
                if (!definition.Cases[index].ContainsUniqueProperty(reader)) continue;
                if (matchedCase >= 0 && matchedCase != index) return null;
                matchedCase = index;
            }
            if (!reader.Read()) return null;
            reader.Skip();
        }

        if (matchedCase >= 0) return definition.Cases[matchedCase].CaseType;
        var requiredMatch = -1;
        for (var index = 0; index < definition.Cases.Length; index++)
        {
            if (!definition.Cases[index].HasAllRequiredProperties(observedProperties)) continue;
            if (requiredMatch >= 0) return null;
            requiredMatch = index;
        }
        if (requiredMatch >= 0) return definition.Cases[requiredMatch].CaseType;
        return definition.DefaultCase;
    }

    private static Type? GetRawFallback(UnionClassifierDefinition definition) =>
        definition.RawFallbackCase is not null && !definition.AllowUnknownDiscriminator ? definition.RawFallbackCase : null;

    private static Type? FindCase(UnionClassifierDefinition definition, Type type)
    {
        foreach (var caseType in definition.CaseTypes)
        {
            if (caseType == type) return caseType;
        }
        return null;
    }

    private static bool TryReadInteger(ref Utf8JsonReader reader, Type type) =>
        type == typeof(int) ? reader.TryGetInt32(out _) :
        type == typeof(uint) ? reader.TryGetUInt32(out _) :
        type == typeof(long) ? reader.TryGetInt64(out _) :
        type == typeof(ulong) && reader.TryGetUInt64(out _);

    private static bool TryReadFloatingPoint(ref Utf8JsonReader reader, Type type) =>
        type == typeof(float) ? reader.TryGetSingle(out _) :
        type == typeof(double) && reader.TryGetDouble(out _);

    private sealed class UnionClassifierDefinition(
        Type[] caseTypes,
        Type[] numericCases,
        Type[] integerCases,
        Type[] floatingPointCases,
        Type[] listCases,
        bool allCasesAreLists,
        string? discriminatorProperty,
        Dictionary<string, Type> discriminatorCases,
        Type? tagFallbackCase,
        Type? rawFallbackCase,
        Type? unknownDiscriminatorFallbackCase,
        Type? defaultCase,
        bool allowUnknownDiscriminator,
        bool discriminatorIsComplete,
        bool needsStructuralFallback,
        UnionCaseClassifierDefinition[] cases)
    {
        public Type[] CaseTypes { get; } = caseTypes;
        public Type[] NumericCases { get; } = numericCases;
        public Type[] IntegerCases { get; } = integerCases;
        public Type[] FloatingPointCases { get; } = floatingPointCases;
        public Type[] ListCases { get; } = listCases;
        public bool AllCasesAreLists { get; } = allCasesAreLists;
        public string? DiscriminatorProperty { get; } = discriminatorProperty;
        public Dictionary<string, Type> DiscriminatorCases { get; } = discriminatorCases;
        public Type? TagFallbackCase { get; } = tagFallbackCase;
        public Type? RawFallbackCase { get; } = rawFallbackCase;
        public Type? UnknownDiscriminatorFallbackCase { get; } = unknownDiscriminatorFallbackCase;
        public Type? DefaultCase { get; } = defaultCase;
        public bool AllowUnknownDiscriminator { get; } = allowUnknownDiscriminator;
        public bool DiscriminatorIsComplete { get; } = discriminatorIsComplete;
        public bool NeedsStructuralFallback { get; } = needsStructuralFallback;
        public UnionCaseClassifierDefinition[] Cases { get; } = cases;
    }

    private sealed class UnionCaseClassifierDefinition(Type caseType, string[] requiredProperties, string[] uniqueProperties)
    {
        public Type CaseType { get; } = caseType;
        public bool HasAllRequiredProperties(HashSet<string> propertyNames)
        {
            if (RequiredProperties.Length == 0) return false;
            foreach (var property in RequiredProperties)
            {
                if (!propertyNames.Contains(property)) return false;
            }
            return true;
        }
        public bool ContainsUniqueProperty(Utf8JsonReader reader)
        {
            foreach (var property in UniqueProperties)
            {
                if (reader.ValueTextEquals(property)) return true;
            }
            return false;
        }
        private string[] RequiredProperties { get; } = requiredProperties;
        private string[] UniqueProperties { get; } = uniqueProperties;
    }
}
